import { Icon } from "@/registry/erbium/ui/icon";
import {
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
  InputGroup,
} from "@/registry/erbium/ui/input-group";

export const defaultProps = {
  align: "inline-start",
  buttonSize: "xs",
  buttonVariant: "ghost",
  className: "",
  placeholder: "Search",
} satisfies {
  align: "inline-start" | "inline-end" | "block-start" | "block-end";
  placeholder: string;
  buttonSize: "xs" | "sm" | "icon-xs" | "icon-sm";
  buttonVariant: "default" | "secondary" | "outline" | "ghost" | "error" | "link";
  className: string;
};

export default function InputGroupPlaygroundExample(
  args: {
    align: "inline-start" | "inline-end" | "block-start" | "block-end";
    placeholder: string;
    buttonSize: "xs" | "sm" | "icon-xs" | "icon-sm";
    buttonVariant: "default" | "secondary" | "outline" | "ghost" | "error" | "link";
    className: string;
  } = defaultProps,
) {
  return (
    <InputGroup className={`w-72 ${args.className}`}>
      <InputGroupAddon align={args.align}>
        <Icon name="search-01" aria-hidden="true" />
      </InputGroupAddon>
      <InputGroupInput placeholder={args.placeholder} />
      <InputGroupAddon align="inline-end">
        <InputGroupButton size={args.buttonSize} variant={args.buttonVariant}>
          Go
        </InputGroupButton>
      </InputGroupAddon>
    </InputGroup>
  );
}
